(7547776, 1208887, 81362, '<td valign="top">First makes me laugh, then makes me linger. Shallow depth of field really contributes to the implied narrative. Original and fascinating, different from typical marketplace images, worthy of high score.</td>', 'First makes me laugh, then makes me linger. Shallow depth of field really contributes to the implied narrative. Original and fascinating, different from typical marketplace images, worthy of high score.', '2017-12-08 08:41:08.000000', NULL, 1),
(7547777, 1208925, 81362, '<td valign="top">Excellent exposure, composition, and sharpness, particularly within the constraints of minimal editing rules. Much for the eye to enjoy here.</td>', 'Excellent exposure, composition, and sharpness, particularly within the constraints of minimal editing rules. Much for the eye to enjoy here.', '2017-12-08 08:43:16.000000', NULL, 1),
(7547778, 1208898, 81362, '<td valign="top">The dark ambiguity stimulates visual exploration and repeated viewing/contemplation -- slowly rewarding the viewer with multiple layers of shifting perceptions.</td>', 'The dark ambiguity stimulates visual exploration and repeated viewing/contemplation -- slowly rewarding the viewer with multiple layers of shifting perceptions.', '2017-12-08 08:54:39.000000', NULL, 1),
(7547780, 1208896, 81362, '<td valign="top">The smile really pulls this together nicely. Good job capturing the moment of hand-off so well.</td>', 'The smile really pulls this together nicely. Good job capturing the moment of hand-off so well.', '2017-12-08 08:56:49.000000', NULL, 1),
